// Load Chogathon 50
import fs from 'fs';

const chogathonWinners = JSON.parse(fs.readFileSync('the-kings-advicer/data/chogathon_top50_winners.json', 'utf8'));

const all302 = [];

// Helper to add
function addWinner(title, event, track, raw_idea, precedent, strat, scamper, framing, benefit, creat) {
  const num = all302.length + 1;
  all302.push({
    id: `win_c11b_${String(num).padStart(3, '0')}`,
    cohort: "cohort_community_meme_302",
    num: num,
    project: `${title} (${event})`,
    section: track,
    raw_idea: raw_idea,
    precedent: precedent,
    condition: "cond_c11b_community_meme_sprint",
    sponsor_benefit: benefit,
    creativity_type: creat,
    precedent_strategy: strat,
    scamper_operator: scamper,
    framing_formula: framing,
    file: "09_community_meme_culture_sprints_302.md",
    line: 30 + num * 8
  });
}

// 1. Chogathon (50)
chogathonWinners.forEach((c) => {
  let strat = "prec_brand_new_native";
  let scamper = "scamper_adapt";
  let framing = "frame_f1_giant_compression";
  let benefit = "benefit_b1_viral_pr";
  let creat = "creat_playful_spectacle";

  if (c.subcategory.includes("viral") || c.subcategory.includes("studio") || c.subcategory.includes("video")) {
    creat = "creat_viral_holder_marketing";
    framing = "frame_f1_giant_compression";
    benefit = "benefit_b1_viral_pr";
    strat = "prec_big_company_port";
  } else if (c.subcategory.includes("multiplayer") || c.subcategory.includes("heist") || c.subcategory.includes("social_virtual")) {
    creat = "creat_multiplayer_social_copresence";
    framing = "frame_f5_physical_verb_dare";
    benefit = "benefit_b4_meter_burn";
    scamper = "scamper_combine";
  } else if (c.subcategory.includes("trading") || c.subcategory.includes("alpha") || c.subcategory.includes("escrow")) {
    creat = "creat_painkiller_bridge";
    framing = "frame_f3_crime_scene_denominator";
    benefit = "benefit_b5_trojan_distribution";
    scamper = "scamper_eliminate";
  } else if (c.subcategory.includes("autonomous") || c.subcategory.includes("erc6551") || c.subcategory.includes("agent")) {
    creat = "creat_mechanism_design";
    framing = "frame_f2_polarity_flip";
    benefit = "benefit_b2_day_zero_proof";
    scamper = "scamper_modify";
  } else if (c.subcategory.includes("floor") || c.subcategory.includes("lending")) {
    creat = "creat_premise_inversion";
    framing = "frame_f2_polarity_flip";
    benefit = "benefit_b4_meter_burn";
    scamper = "scamper_reverse";
  }

  addWinner(
    c.title,
    `Chogathon 2026 — Rank #${c.rank}, $${c.prize_usd}`,
    "A. Chogathon — Monad Genesis NFT & Community Sprint (50 Winners, 2026)",
    `${c.tagline || c.why_it_placed} Built by ${c.builder}.`,
    `**"${c.title === 'CHOG STUDIO' ? 'CapCut for NFT Avatars' : c.title === 'Grand Theft Chog' ? 'GTA Heist for Token Vaults' : 'Community Utility'}"** (${strat === 'prec_big_company_port' ? 'Category Port' : 'Brand-New Native'})`,
    strat, scamper, framing, benefit, creat
  );
});

